import{_ as a,o as e,c as i,a2 as d}from"./chunks/framework.Bqa2y7hU.js";const u=JSON.parse('{"title":"系统要求","description":"部署 Xiaoyi_QQ_V4 需要的操作系统、硬件、数据库与网络条件。","frontmatter":{"title":"系统要求","description":"部署 Xiaoyi_QQ_V4 需要的操作系统、硬件、数据库与网络条件。"},"headers":[],"relativePath":"guide/requirements.md","filePath":"guide/requirements.md","lastUpdated":1789447036000}'),s={name:"guide/requirements.md"};function r(l,t,o,n,h,c){return e(),i("div",null,[...t[0]||(t[0]=[d(`<h1 id="系统要求" tabindex="-1">系统要求 <a class="header-anchor" href="#系统要求" aria-label="Permalink to &quot;系统要求&quot;">​</a></h1><p>部署前对照这张表检查一遍，绝大多数「装不上」都是这里少了一项。</p><h2 id="运行环境" tabindex="-1">运行环境 <a class="header-anchor" href="#运行环境" aria-label="Permalink to &quot;运行环境&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>要求</th><th>说明</th></tr></thead><tbody><tr><td>操作系统</td><td>Ubuntu 24.04 x86_64（amd64）</td><td>这是官方构建与验证环境。Debian 12 等同代发行版一般可用；CentOS 7 等老系统不建议</td></tr><tr><td>CPU</td><td>1 核起</td><td>框架本身很轻，插件多、机器人群多时按需加核</td></tr><tr><td>内存</td><td>1 GB 起</td><td>建议 2 GB 以上，留出数据库与插件运行空间</td></tr><tr><td>磁盘</td><td>2 GB 起</td><td>消息记录与日志会持续写入，按业务量预留</td></tr><tr><td>PostgreSQL</td><td>12 及以上</td><td>可以装在同一台机器，也可以是已有的独立实例</td></tr><tr><td>网络</td><td>能访问外网</td><td>用于连接平台网关、调用外部接口、发邮件等</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">不需要的东西</p><p>不需要 Redis、不需要消息队列、不需要 Node.js、不需要单独部署 Web 服务器（前端已内嵌在程序里）。</p></div><h2 id="数据库" tabindex="-1">数据库 <a class="header-anchor" href="#数据库" aria-label="Permalink to &quot;数据库&quot;">​</a></h2><ul><li>需要一个<strong>可用的 PostgreSQL 实例</strong>，并准备好连接信息：地址、端口、用户名、密码、库名。</li><li>建表和升级由程序启动时<strong>自动完成</strong>，你不需要手工导入 SQL。</li><li>建议为该实例设置定期备份（见 <a href="/RuaBot.Doc/deploy/ops">备份与运维</a>）。</li></ul><h2 id="系统依赖" tabindex="-1">系统依赖 <a class="header-anchor" href="#系统依赖" aria-label="Permalink to &quot;系统依赖&quot;">​</a></h2><p>如果使用提供的安装包，安装脚本会处理依赖；如果是<strong>手动运行二进制</strong>，需要确认系统里已有：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 动态链接版需要的两个运行库</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libpq5</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libssl3t64</span></span></code></pre></div><details class="details custom-block"><summary>静态链接版</summary><p>如果分发的是静态链接版本，则不需要额外安装运行库，可以直接运行。</p></details><h2 id="端口" tabindex="-1">端口 <a class="header-anchor" href="#端口" aria-label="Permalink to &quot;端口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>端口</th><th>用途</th><th>是否必须对外开放</th></tr></thead><tbody><tr><td><code>8080</code></td><td>管理控制台、安装向导、Webhook 回调、开放 API</td><td>需要（建议经反向代理 + HTTPS）</td></tr><tr><td><code>8081</code></td><td>适配器数据面：OneBot 反向 WebSocket 接入</td><td>仅在用 OneBot 11 时需要</td></tr><tr><td><code>5432</code></td><td>PostgreSQL 默认端口</td><td>数据库不在本机时需要放通</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">端口冲突</p><p>如果 <code>8080</code> / <code>8081</code> 已被占用，程序会启动失败并提示地址被占用。可以在配置文件里改成其他端口，改完重启服务。</p></div><h2 id="网络与域名" tabindex="-1">网络与域名 <a class="header-anchor" href="#网络与域名" aria-label="Permalink to &quot;网络与域名&quot;">​</a></h2><ul><li><strong>只用 WebSocket 网关方式接 QQ 官方机器人</strong>：不需要公网域名，框架主动连平台。</li><li><strong>用 Webhook 回调方式</strong>：平台要主动回调你的服务器，<strong>必须有公网可访问的地址</strong>，并在「平台设置 → 站点」里把协议与域名配好，否则回调地址会退化成内网地址。</li><li><strong>用 OneBot 11</strong>：实现端要能连上你的 <code>8081</code> 端口，通常是同机部署或同内网。</li></ul><h2 id="客户端" tabindex="-1">客户端 <a class="header-anchor" href="#客户端" aria-label="Permalink to &quot;客户端&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>要求</th></tr></thead><tbody><tr><td>管理控制台</td><td>现代浏览器（Chrome / Edge / Safari / Firefox 近两年版本）</td></tr><tr><td>QQ 官方机器人相关功能</td><td>较新版本的 QQ 客户端（按钮、Markdown 等能力依赖客户端支持）</td></tr></tbody></table><h2 id="授权文件" tabindex="-1">授权文件 <a class="header-anchor" href="#授权文件" aria-label="Permalink to &quot;授权文件&quot;">​</a></h2><p>程序启动时需要一个由服务商提供的授权文件，放到<strong>程序同目录</strong>即可。</p><ul><li>授权与服务器绑定：<strong>换服务器或换机器需要联系服务商重新签发</strong>。</li><li>授权到期后程序会停止运行，续期后重启即可。</li><li>授权文件请妥善保管，不要放进任何公开仓库或分享给他人。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/RuaBot.Doc/deploy/install">安装</a>：开始部署</li><li><a href="/RuaBot.Doc/deploy/config">首次配置</a>：装完之后怎么初始化</li><li><a href="/RuaBot.Doc/faq">常见问题</a>：环境相关的典型问题</li></ul>`,23)])])}const b=a(s,[["render",r]]);export{u as __pageData,b as default};
